-- Ticket C3: add UNIQUE constraint on orders(external_ref) without blocking app traffic.
-- Plan:
--   1. Build the unique index CONCURRENTLY (no write-blocking lock; autocommit, so no outer transaction).
--   2. Promote the valid index to a UNIQUE constraint. This needs ACCESS EXCLUSIVE, which queues behind the
--      long-running analytics read transactions, so it is attempted with a short lock_timeout and retried
--      in the gaps between analytics transactions. Each attempt blocks app traffic for at most 150 ms.

-- Record the script start time for the overall deadline (session-level placeholder, no server/role settings changed).
SELECT set_config('migration.t0', clock_timestamp()::text, false);

-- Remove any INVALID leftover index from an earlier failed build with the same name (no-op on a clean database).
DROP INDEX CONCURRENTLY IF EXISTS orders_external_ref_key;

-- Phase 1: concurrent unique build. Does not block INSERT/UPDATE/DELETE. Fails if duplicates exist (none expected).
CREATE UNIQUE INDEX CONCURRENTLY orders_external_ref_key ON orders (external_ref);

-- Phase 2: promote the valid index to a UNIQUE constraint (catalog-only change, no table scan),
-- retrying under a short lock_timeout until the ACCESS EXCLUSIVE lock is granted.
DO $mig$
DECLARE
  deadline timestamptz := current_setting('migration.t0')::timestamptz + interval '55 seconds';
BEGIN
  PERFORM set_config('lock_timeout', '150ms', true);
  LOOP
    BEGIN
      ALTER TABLE orders
        ADD CONSTRAINT orders_external_ref_key UNIQUE USING INDEX orders_external_ref_key;
      EXIT;
    EXCEPTION WHEN lock_not_available THEN
      IF clock_timestamp() > deadline THEN
        RAISE;
      END IF;
      PERFORM pg_sleep(0.1);
    END;
  END LOOP;
END
$mig$;
```

